import { useEffect, useMemo, useState } from "react";
import { api } from "./api";

const initialForm = {
  name: "",
  email: "",
  phone: "",
  line1: "",
  line2: "",
  city: "",
  state: "",
  postalCode: "",
};
const money = (value) => `₹${value.toLocaleString("en-IN")}`;

function Modal({ title, children, close }) {
  return (
    <div
      className="overlay"
      onMouseDown={(event) => event.target === event.currentTarget && close()}
    >
      <div className="modal">
        <button className="close" onClick={close} aria-label="Close">
          ×
        </button>
        <h2>{title}</h2>
        {children}
      </div>
    </div>
  );
}
function Header({ cartCount, openCart, openAuth, user, logout }) {
  return (
    <>
      <div className="announcement">
        ✦ 100% AYURVEDIC ✦ &nbsp; THOUGHTFULLY CRAFTED WELLNESS &nbsp; ✦ FREE
        DELIVERY ON ORDERS ABOVE ₹499 ✦
      </div>
      <header className="header">
        <a className="logo" href="#top" aria-label="Amrit Vedham home">
          <img src="data:image/jpeg;base64," alt="Amrit Vedham" />
          <span>
            AMRIT
            <br />
            <small>VEDHAM</small>
          </span>
        </a>
        <nav className="navlinks">
          <a href="#top">Home</a>
          <a href="#shop">Shop</a>
          <a href="#shop">King Kesari</a>
          <a href="#shop">Ortho Amrit</a>
          <a href="#about">Our Story</a>
          {user?.role === "admin" && <a href="#admin">Admin</a>}
        </nav>
        <div className="icons">
          <button
            className="iconbtn mobile-menu"
            onClick={() =>
              document
                .getElementById("shop")
                ?.scrollIntoView({ behavior: "smooth" })
            }
            aria-label="Menu"
          >
            ☰
          </button>
          <button
            className="iconbtn"
            onClick={() => document.getElementById("search")?.focus()}
            aria-label="Search"
          >
            ⌕
          </button>
          {user ? (
            <button className="account" onClick={logout} title="Log out">
              {user.name.split(" ")[0]} · Log out
            </button>
          ) : (
            <button className="account" onClick={openAuth}>
              Sign in
            </button>
          )}
          <button className="iconbtn" onClick={openCart} aria-label="Cart">
            🛒<span className="cartcount">{cartCount}</span>
          </button>
        </div>
      </header>
    </>
  );
}
function ProductCard({ product, add, wishlist, toggleWishlist }) {
  return (
    <article className="card">
      <div className="product-image">
        <span className="tag">{product.tag}</span>
        <button
          className="heart"
          aria-label="Add to wishlist"
          onClick={() => toggleWishlist(product._id)}
          style={{ color: wishlist ? "#9d4a45" : "#b5a075" }}
        >
          {wishlist ? "♥" : "♡"}
        </button>
        <img src={product.image} alt={product.name} />
      </div>
      <div className="details">
        <div className="category">{product.category}</div>
        <h3>{product.name}</h3>
        <div className="desc">{product.description}</div>
        <div className="weight">{product.weight}</div>
        <div className="price-row">
          <span className="price">{money(product.price)}</span>
          {product.mrp && <span className="mrp">{money(product.mrp)}</span>}
        </div>
        <span className="saving">
          {product.name.toLowerCase().includes("ortho")
            ? "Ortho Amrit Collection"
            : "King Kesari Collection"}
        </span>
        <button className="add" onClick={() => add(product)}>
          ADD TO CART
        </button>
      </div>
    </article>
  );
}
function CartModal({ cart, close, update, checkout }) {
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);
  return (
    <Modal title="Your Cart" close={close}>
      {cart.length ? (
        <>
          <div className="cart-lines">
            {cart.map((item) => (
              <div className="cart-line" key={item._id}>
                <img src={item.image} alt="" />
                <div>
                  <b>{item.name}</b>
                  <small>{money(item.price)} each</small>
                </div>
                <div className="quantity">
                  <button onClick={() => update(item._id, item.quantity - 1)}>
                    -
                  </button>
                  <span>{item.quantity}</span>
                  <button onClick={() => update(item._id, item.quantity + 1)}>
                    +
                  </button>
                </div>
              </div>
            ))}
          </div>
          <div className="cart-total">
            <b>Total</b>
            <strong>{money(total)}</strong>
          </div>
          <button className="add" onClick={checkout}>
            PROCEED TO CHECKOUT
          </button>
        </>
      ) : (
        <p className="empty">
          Your cart is empty. Add a wellness essential to begin.
        </p>
      )}
    </Modal>
  );
}
function AuthModal({ close, submit }) {
  const [mode, setMode] = useState("login");
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [error, setError] = useState("");
  const send = async (event) => {
    event.preventDefault();
    try {
      await submit(mode, form);
      close();
    } catch (err) {
      setError(err.message);
    }
  };
  return (
    <Modal
      title={mode === "login" ? "Welcome back" : "Create your account"}
      close={close}
    >
      <form className="form" onSubmit={send}>
        {mode === "register" && (
          <input
            required
            placeholder="Full name"
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />
        )}
        <input
          required
          type="email"
          placeholder="Email address"
          value={form.email}
          onChange={(e) => setForm({ ...form, email: e.target.value })}
        />
        <input
          required
          minLength="8"
          type="password"
          placeholder="Password (8+ characters)"
          value={form.password}
          onChange={(e) => setForm({ ...form, password: e.target.value })}
        />
        {error && <div className="error">{error}</div>}
        <button className="add">
          {mode === "login" ? "SIGN IN" : "CREATE ACCOUNT"}
        </button>
      </form>
      <button
        className="text-button"
        onClick={() => setMode(mode === "login" ? "register" : "login")}
      >
        {mode === "login"
          ? "New here? Create an account"
          : "Already registered? Sign in"}
      </button>
    </Modal>
  );
}
function CheckoutModal({ close, user, cart, submit }) {
  const [form, setForm] = useState({
    ...initialForm,
    name: user?.name || "",
    email: user?.email || "",
  });
  const [error, setError] = useState("");
  const send = async (event) => {
    event.preventDefault();
    try {
      await submit(form);
    } catch (err) {
      setError(err.message);
    }
  };
  return (
    <Modal title="Checkout" close={close}>
      <form className="form" onSubmit={send}>
        <div className="checkout-summary">
          {cart.length} item(s) ·{" "}
          {money(
            cart.reduce((sum, item) => sum + item.price * item.quantity, 0),
          )}
        </div>
        <input
          required
          placeholder="Full name"
          value={form.name}
          onChange={(e) => setForm({ ...form, name: e.target.value })}
        />
        <input
          required
          type="email"
          placeholder="Email address"
          value={form.email}
          onChange={(e) => setForm({ ...form, email: e.target.value })}
        />
        <input
          required
          placeholder="Phone number"
          value={form.phone}
          onChange={(e) => setForm({ ...form, phone: e.target.value })}
        />
        <input
          required
          placeholder="Address line 1"
          value={form.line1}
          onChange={(e) => setForm({ ...form, line1: e.target.value })}
        />
        <input
          placeholder="Address line 2"
          value={form.line2}
          onChange={(e) => setForm({ ...form, line2: e.target.value })}
        />
        <div className="form-grid">
          <input
            required
            placeholder="City"
            value={form.city}
            onChange={(e) => setForm({ ...form, city: e.target.value })}
          />
          <input
            required
            placeholder="State"
            value={form.state}
            onChange={(e) => setForm({ ...form, state: e.target.value })}
          />
        </div>
        <input
          required
          placeholder="Postal code"
          value={form.postalCode}
          onChange={(e) => setForm({ ...form, postalCode: e.target.value })}
        />
        {error && <div className="error">{error}</div>}
        <button className="add">PAY SECURELY WITH RAZORPAY</button>
      </form>
    </Modal>
  );
}
function AdminPanel({ token, products, refresh, orders, notify }) {
  const [editing, setEditing] = useState(null);
  const [imageFile, setImageFile] = useState(null);
  const [form, setForm] = useState({
    name: "",
    category: "",
    tag: "",
    description: "",
    price: "",
    weight: "",
    image: "/assets/product1.jpeg",
  });
  const save = async (event) => {
    event.preventDefault();
    try {
      const image = imageFile
        ? (await api.uploadImage(token, imageFile)).image
        : form.image;
      const payload = { ...form, image, price: Number(form.price) };
      editing
        ? await api.updateProduct(token, editing, payload)
        : await api.createProduct(token, payload);
      setEditing(null);
      setImageFile(null);
      setForm({
        name: "",
        category: "",
        tag: "",
        description: "",
        price: "",
        weight: "",
        image: "/assets/product1.jpeg",
      });
      await refresh();
      notify("Product saved");
    } catch (err) {
      notify(err.message);
    }
  };
  return (
    <section id="admin" className="admin">
      <div className="admin-heading">
        <div>
          <div className="kicker">ADMINISTRATION</div>
          <h2>Store management</h2>
        </div>
        <button
          className="pill-button"
          onClick={() => {
            setEditing(null);
            setImageFile(null);
            setForm({
              name: "",
              category: "",
              tag: "",
              description: "",
              price: "",
              weight: "",
              image: "/assets/product1.jpeg",
            });
          }}
        >
          NEW PRODUCT
        </button>
      </div>
      <div className="admin-grid">
        <form className="form admin-form" onSubmit={save}>
          <h3>{editing ? "Edit product" : "Add product"}</h3>
          {[
            "name",
            "category",
            "tag",
            "description",
            "price",
            "weight",
          ].map((field) => (
            <input
              required
              key={field}
              type={field === "price" ? "number" : "text"}
              placeholder={field[0].toUpperCase() + field.slice(1)}
              value={form[field]}
              onChange={(e) => setForm({ ...form, [field]: e.target.value })}
            />
          ))}
          <label className="file-field">
            Product image
            <input
              required={!editing}
              type="file"
              accept="image/jpeg,image/png,image/webp"
              onChange={(event) => setImageFile(event.target.files?.[0] || null)}
            />
            <small>{imageFile ? imageFile.name : editing ? "Current image will be kept" : "JPEG, PNG, or WebP up to 5 MB"}</small>
          </label>
          <button className="add">SAVE PRODUCT</button>
        </form>
        <div className="admin-table">
          <h3>Products</h3>
          {products.map((product) => (
            <div className="admin-row" key={product._id}>
              <span>
                {product.name}
                <small>{money(product.price)}</small>
              </span>
              <button
                onClick={() => {
                  setEditing(product._id);
                  setImageFile(null);
                  setForm(product);
                }}
              >
                Edit
              </button>
              <button
                onClick={async () => {
                  await api.deleteProduct(token, product._id);
                  await refresh();
                  notify("Product archived");
                }}
              >
                Archive
              </button>
            </div>
          ))}
        </div>
        <div className="admin-table">
          <h3>Orders</h3>
          {orders.map((order) => (
            <div className="admin-row" key={order._id}>
              <span>
                #{order._id.slice(-6)}
                <small>
                  {order.customer.name} · {money(order.total)} ·{" "}
                  {order.paymentStatus}
                </small>
              </span>
              <select
                value={order.status}
                onChange={async (e) => {
                  await fetch(`/api/admin/orders/${order._id}`, {
                    method: "PATCH",
                    headers: {
                      "Content-Type": "application/json",
                      Authorization: `Bearer ${token}`,
                    },
                    body: JSON.stringify({ status: e.target.value }),
                  });
                  notify("Order updated");
                }}
              >
                <option>pending_payment</option>
                <option>placed</option>
                <option>processing</option>
                <option>shipped</option>
                <option>delivered</option>
                <option>cancelled</option>
              </select>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState(() =>
    JSON.parse(localStorage.getItem("amrit-cart") || "[]"),
  );
  const [user, setUser] = useState(() =>
    JSON.parse(localStorage.getItem("amrit-user") || "null"),
  );
  const [token, setToken] = useState(() => localStorage.getItem("amrit-token"));
  const [orders, setOrders] = useState([]);
  const [adminOrders, setAdminOrders] = useState([]);
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState("featured");
  const [modal, setModal] = useState(null);
  const [wishlist, setWishlist] = useState(() =>
    JSON.parse(localStorage.getItem("amrit-wishlist") || "[]"),
  );
  const [toast, setToast] = useState("");
  const notify = (message) => {
    setToast(message);
    window.clearTimeout(window.toastTimer);
    window.toastTimer = window.setTimeout(() => setToast(""), 2400);
  };
  const loadProducts = async () => setProducts(await api.products());
  useEffect(() => {
    loadProducts().catch((err) => notify(err.message));
  }, []);
  useEffect(() => {
    localStorage.setItem("amrit-cart", JSON.stringify(cart));
  }, [cart]);
  useEffect(() => {
    localStorage.setItem("amrit-wishlist", JSON.stringify(wishlist));
  }, [wishlist]);
  useEffect(() => {
    if (token) {
      api
        .orders(token)
        .then(setOrders)
        .catch(() => {});
      if (user?.role === "admin")
        api
          .adminOrders(token)
          .then(setAdminOrders)
          .catch(() => {});
    }
  }, [token, user]);
  const visible = useMemo(() => {
    const result = products.filter((p) =>
      `${p.name} ${p.category} ${p.description}`
        .toLowerCase()
        .includes(query.toLowerCase()),
    );
    return sort === "low"
      ? result.sort((a, b) => a.price - b.price)
      : sort === "high"
        ? result.sort((a, b) => b.price - a.price)
        : result;
  }, [products, query, sort]);
  const add = (product) => {
    setCart((current) => {
      const found = current.find((item) => item._id === product._id);
      return found
        ? current.map((item) =>
            item._id === product._id
              ? { ...item, quantity: item.quantity + 1 }
              : item,
          )
        : [...current, { ...product, quantity: 1 }];
    });
    notify(`${product.name} added to cart`);
  };
  const updateCart = (id, quantity) =>
    setCart((current) =>
      quantity < 1
        ? current.filter((item) => item._id !== id)
        : current.map((item) =>
            item._id === id ? { ...item, quantity } : item,
          ),
    );
  const authenticate = async (mode, form) => {
    const result = await (mode === "login"
      ? api.login(form)
      : api.register(form));
    setToken(result.token);
    setUser(result.user);
    localStorage.setItem("amrit-token", result.token);
    localStorage.setItem("amrit-user", JSON.stringify(result.user));
    notify(`Welcome, ${result.user.name}`);
  };
  const checkout = () => {
    if (!token) return setModal("auth");
    setModal("checkout");
  };
  const submitOrder = async (form) => {
    const result = await api.createOrder(token, {
      items: cart.map((item) => ({
        productId: item._id,
        quantity: item.quantity,
      })),
      customer: { name: form.name, email: form.email, phone: form.phone },
      address: {
        line1: form.line1,
        line2: form.line2,
        city: form.city,
        state: form.state,
        postalCode: form.postalCode,
      },
    });
    if (!result.payment) {
      setCart([]);
      setModal(null);
      notify(result.message);
      return;
    }
    if (!window.Razorpay) {
      const script = document.createElement("script");
      script.src = "https://checkout.razorpay.com/v1/checkout.js";
      document.body.appendChild(script);
      await new Promise((resolve) => {
        script.onload = resolve;
      });
    }
    await new Promise((resolve, reject) => {
      const payment = new window.Razorpay({
        key: result.payment.key,
        amount: result.payment.amount,
        currency: result.payment.currency,
        name: "Amrit Vedham",
        description: "Ayurvedic wellness order",
        order_id: result.payment.id,
        prefill: { name: form.name, email: form.email, contact: form.phone },
        handler: async (response) => {
          try {
            await api.verifyPayment(token, result.order._id, response);
            setCart([]);
            setModal(null);
            notify("Payment verified. Your order is placed.");
            setOrders(await api.orders(token));
            resolve();
          } catch (err) {
            reject(err);
          }
        },
        modal: { ondismiss: resolve },
      });
      payment.open();
    });
  };
  const logout = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem("amrit-user");
    localStorage.removeItem("amrit-token");
    notify("You have been signed out");
  };
  return (
    <div id="top">
      <Header
        cartCount={cart.reduce((sum, item) => sum + item.quantity, 0)}
        openCart={() => setModal("cart")}
        openAuth={() => setModal("auth")}
        user={user}
        logout={logout}
      />
      <main>
        <section className="intro">
          <div className="kicker">AMRIT VEDHAM</div>
          <h1>The Shop</h1>
          <div className="hindi">आयुर्वेद — प्रकृति का वरदान</div>
          <p>
            Discover Ayurvedic wellness inspired by traditional ingredients and
            everyday care. Explore the Amrit Vedham collection, thoughtfully
            presented for your daily wellness routine.
          </p>
          <span className="pill">OUR SIGNATURE PRODUCTS</span>
        </section>
        <section id="shop">
          <div className="shopbar">
            <div>
              <h2>Shop All Products</h2>
              <p>Explore the Amrit Vedham collection</p>
            </div>
            <div className="tools">
              <input
                className="search"
                id="search"
                type="search"
                placeholder="Search products..."
                aria-label="Search products"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
              />
              <select
                value={sort}
                onChange={(e) => setSort(e.target.value)}
                aria-label="Sort products"
              >
                <option value="featured">Featured</option>
                <option value="low">Price: low to high</option>
                <option value="high">Price: high to low</option>
              </select>
            </div>
          </div>
          <div className="products">
            {visible.map((product) => (
              <ProductCard
                key={product._id}
                product={product}
                add={add}
                wishlist={wishlist.includes(product._id)}
                toggleWishlist={(id) =>
                  setWishlist((current) =>
                    current.includes(id)
                      ? current.filter((value) => value !== id)
                      : [...current, id],
                  )
                }
              />
            ))}
          </div>
        </section>
        <section className="trust">
          <div className="trust-item">
            <div className="trust-icon">❋</div>
            <b>Ayurvedic Tradition</b>Inspired by heritage
          </div>
          <div className="trust-item">
            <div className="trust-icon">♧</div>
            <b>Product Transparency</b>Check label details
          </div>
          <div className="trust-item">
            <div className="trust-icon">◇</div>
            <b>Customer Support</b>Here to help
          </div>
          <div className="trust-item">
            <div className="trust-icon">♡</div>
            <b>Thoughtful Wellness</b>For everyday routines
          </div>
        </section>
        <section id="about" className="about">
          <div className="kicker">OUR PHILOSOPHY</div>
          <h2>Rooted in Ayurveda</h2>
          <p>
            Amrit Vedham brings together traditional Ayurvedic inspiration and a
            simple shopping experience. Product descriptions, prices and pack
            sizes should be confirmed against the final product label before
            publishing.
          </p>
        </section>
        {user && (
          <section className="orders">
            <div className="kicker">YOUR ACCOUNT</div>
            <h2>Order history</h2>
            {orders.length ? (
              orders.map((order) => (
                <div className="order-line" key={order._id}>
                  <span>
                    #{order._id.slice(-6)}
                    <small>
                      {new Date(order.createdAt).toLocaleDateString("en-IN")} ·{" "}
                      {order.items.length} item(s)
                    </small>
                  </span>
                  <b>{money(order.total)}</b>
                  <em className={`status ${order.paymentStatus}`}>
                    {order.paymentStatus}
                  </em>
                  <em className={`status ${order.status}`}>{order.status}</em>
                </div>
              ))
            ) : (
              <p>No orders yet.</p>
            )}
          </section>
        )}
        {user?.role === "admin" && (
          <AdminPanel
            token={token}
            products={products}
            refresh={loadProducts}
            orders={adminOrders}
            notify={notify}
          />
        )}
      </main>
      <footer className="footer">
        <div>
          <a className="logo" href="#top">
            <img src="data:image/jpeg;base64," alt="" />
            <span>
              AMRIT
              <br />
              <small>VEDHAM</small>
            </span>
          </a>
          <p>Thoughtfully crafted wellness, rooted in Ayurveda.</p>
        </div>
        <div>
          <h4>SHOP</h4>
          <a href="#shop">All products</a>
          <br />
          <a href="#about">Our philosophy</a>
        </div>
        <div>
          <h4>ACCOUNT</h4>
          <a
            href="#"
            onClick={(e) => {
              e.preventDefault();
              user ? logout() : setModal("auth");
            }}
          >
            {user ? "Sign out" : "Sign in"}
          </a>
          <br />
          <a href="#shop">Customer care</a>
        </div>
        <div>
          <h4>CONTACT</h4>
          <p>Made with care in India</p>
        </div>
      </footer>
      <div className="copyright">© 2026 Amrit Vedham. All rights reserved.</div>
      {modal === "cart" && (
        <CartModal
          cart={cart}
          close={() => setModal(null)}
          update={updateCart}
          checkout={checkout}
        />
      )}
      {modal === "auth" && (
        <AuthModal close={() => setModal(null)} submit={authenticate} />
      )}
      {modal === "checkout" && (
        <CheckoutModal
          close={() => setModal(null)}
          user={user}
          cart={cart}
          submit={submitOrder}
        />
      )}
      <div className={`toast ${toast ? "show" : ""}`} role="status">
        {toast}
      </div>
    </div>
  );
}
